             .arg(id);
     case PL_COMP_ZSTACK:
         return QStringLiteral("import QtQuick 2.15\nItem { objectName: \"pl%1\" }").arg(id);
     case PL_COMP_GRID:
     case PL_COMP_LAZY_VGRID:
     case PL_COMP_LAZY_HGRID:
