// Apply a stack's padding to its inner layout (anchors.margins) + the wrapper's
// `plPad` (drives implicit size so the wrapper hugs padded content).
void applyPadding(uint32_t id, const char *edge, float value) {
    QQuickItem *item = findWidget(id);
